  ('S01', 'Giả danh công an, yêu cầu chuyển vào ''tài khoản an toàn''', 'G1', 'DRAIN', 'Y', '{"keywords": ["cong an", "vien kiem sat", "tai khoan an toan", "dieu tra", "phong toa", "lenh bat"], "recent_events": ["SAVINGS_CLOSED", "LIMIT_RAISED"], "new_beneficiary": true, "min_drain_ratio": 0.7, "min_amount": 50000000}'::jsonb, '{"SALARY": ["Có ai tự xưng là công an hoặc viện kiểm sát yêu cầu bạn chuyển khoản này không?"], "HNW": ["Khoản chuyển này có liên quan tới một cuộc gọi từ cơ quan chức năng không?"], "SENIOR": ["Bác ơi, có ai gọi điện xưng là công an rồi bảo bác chuyển tiền đi không ạ?"]}'::jsonb, '["Có, họ gọi điện cho tôi", "Không, tôi tự chuyển", "Tôi không chắc"]'::jsonb, 'Công an không bao giờ yêu cầu chuyển tiền', 'Cơ quan công an, viện kiểm sát và tòa án KHÔNG BAO GIỜ làm việc qua điện thoại và không bao giờ yêu cầu chuyển tiền vào ''tài khoản an toàn'' để chứng minh vô tội. Mọi lệnh triệu tập đều bằng văn bản gửi tới nơi cư trú. Nếu ai đó gọi điện, gây áp lực về thời gian và yêu cầu giữ bí mật với người thân, đó chắc chắn là lừa đảo. Hãy dừng giao dịch và gọi tới số hotline ngân hàng in trên thẻ của bạn.', 'cancel', 1, 'ACTIVE'),
  ('S02', 'Giả danh nhân viên ngân hàng, moi OTP hoặc mật khẩu', 'G1', 'SINGLE', 'Y', '{"keywords": ["otp", "ma xac thuc", "xac thuc", "mat khau", "bao mat", "nhan vien ngan hang", "khoa tai khoan", "nang cap he thong", "nang cap bao mat"], "recent_events": ["PASSWORD_RESET", "NEW_DEVICE_LOGIN"], "session_flags": ["on_call"], "new_beneficiary": true}'::jsonb, '{"SALARY": ["Có ai vừa yêu cầu bạn đọc mã OTP hoặc mật khẩu qua điện thoại không?"], "HNW": ["Bạn có vừa cung cấp mã xác thực cho người tự xưng là nhân viên ngân hàng?"], "SENIOR": ["Bác có vừa đọc mã số nào trong tin nhắn cho người ta nghe không ạ?"]}'::jsonb, '["Có, tôi vừa đọc mã cho họ", "Không", "Tôi có bấm vào một đường link lạ"]'::jsonb, 'Ngân hàng không bao giờ hỏi OTP', 'Không một nhân viên ngân hàng thật nào hỏi mã OTP, mật khẩu hay mã PIN của bạn — họ không cần và cũng không được phép. Mã OTP là chữ ký điện tử của riêng bạn: đọc cho người khác nghe đồng nghĩa với việc ký vào lệnh chuyển tiền của họ. Nếu bạn vừa cung cấp mã, hãy đổi mật khẩu ngay và gọi hotline ngân hàng.', 'cancel', 2, 'ACTIVE'),
  ('S03', 'Deepfake video call giả người thân mượn tiền gấp', 'G2', 'SINGLE', 'Y', '{"keywords": ["gap", "muon tien", "tai nan", "cap cuu", "chuyen gap", "con trai", "con gai"], "new_beneficiary": true, "min_amount": 20000000, "session_flags": ["on_call"]}'::jsonb, '{"SALARY": ["Bạn có gọi lại cho người thân đó bằng số điện thoại bạn vẫn lưu không?"], "HNW": ["Yêu cầu chuyển gấp này đến từ video call hay tin nhắn?"], "SENIOR": ["Bác đã gọi lại cho con cháu bằng số quen để hỏi lại chưa ạ?"]}'::jsonb, '["Tôi gọi lại rồi, đúng là người nhà", "Chưa gọi lại", "Họ gọi video cho tôi"]'::jsonb, 'Hãy gọi lại bằng số bạn vẫn lưu', 'Công nghệ deepfake hiện có thể dựng khuôn mặt và giọng nói người thân của bạn trong một cuộc gọi video ngắn. Dấu hiệu nhận biết: hình ảnh mờ hoặc giật, người gọi viện lý do mạng kém để cúp nhanh, và luôn hối thúc chuyển tiền gấp vào một tài khoản lạ. Cách kiểm tra chắc chắn nhất: cúp máy và tự gọi lại bằng số điện thoại bạn vẫn lưu trong danh bạ, hoặc hỏi một câu chỉ hai người mới biết.', 'hold', 2, 'ACTIVE'),
  ('S04', 'Sàn đầu tư ảo cam kết lợi nhuận cao', 'G3', 'SERIES', 'Y', '{"keywords": ["dau tu", "san", "tien ao", "loi nhuan", "chung khoan quoc te", "forex", "nap tien"], "new_beneficiary": true, "inbound_bait": true, "min_series_14d": 2}'::jsonb, '{"SALARY": ["Sàn đầu tư này có được Ủy ban Chứng khoán Nhà nước cấp phép không?"], "HNW": ["Bạn đã rút được tiền gốc ra khỏi sàn này lần nào chưa?"], "SENIOR": ["Bác có ai giới thiệu sàn đầu tư này qua mạng không ạ?"]}'::jsonb, '["Tôi đã rút được tiền vài lần", "Chưa rút được lần nào", "Có người quen giới thiệu"]'::jsonb, 'Rút được lần đầu là cách họ lấy niềm tin', 'Mô hình sàn đầu tư ảo luôn cho bạn rút được vài lần đầu với số nhỏ — đó chính là khoản ''tiền mồi'' để bạn tin tưởng và nạp số lớn hơn. Đến khi bạn nạp khoản lớn, sàn sẽ báo lỗi hệ thống, yêu cầu nộp thêm ''thuế'' hoặc ''phí rút'', rồi biến mất. Không có kênh đầu tư hợp pháp nào cam kết lợi nhuận cố định trên 15%/năm. Hãy tra cứu giấy phép trên trang của Ủy ban Chứng khoán Nhà nước trước khi nạp thêm bất kỳ đồng nào.', 'hold', 3, 'ACTIVE'),
  ('S05', 'Việc nhẹ lương cao, nạp tiền làm nhiệm vụ', 'G3', 'SERIES', 'Y', '{"keywords": ["nhiem vu", "hoa hong", "don hang", "viec lam online", "cong tac vien", "nap de rut"], "new_beneficiary": true, "inbound_bait": true, "min_series_14d": 3}'::jsonb, '{"SALARY": ["Bạn có phải nạp tiền trước để nhận hoa hồng cho nhiệm vụ này không?"], "HNW": ["Công việc này có yêu cầu bạn ứng tiền cho từng đơn hàng?"], "SENIOR": ["Bác có phải chuyển tiền trước rồi mới được nhận hoa hồng không ạ?"]}'::jsonb, '["Có, tôi phải nạp trước", "Không", "Nhiệm vụ này là nhiệm vụ cuối"]'::jsonb, 'Việc làm thật không bắt bạn nạp tiền', 'Không có công việc hợp pháp nào yêu cầu người lao động nạp tiền trước để nhận hoa hồng. Mô hình này luôn diễn ra theo cùng một kịch bản: vài nhiệm vụ đầu trả hoa hồng đầy đủ, rồi số tiền yêu cầu nạp tăng dần, và ở nhiệm vụ cuối họ báo bạn ''thao tác sai'' nên phải nạp thêm để lấy lại toàn bộ. Số tiền bạn đã nạp càng lớn thì áp lực nạp tiếp càng mạnh — đó là lúc nên dừng lại hoàn toàn.', 'hold', 3, 'ACTIVE'),
  ('S06', 'Mua bán online, yêu cầu đặt cọc trước', 'G4', 'SINGLE', 'Y', '{"keywords": ["dat coc", "giu cho", "chuyen khoan truoc", "ship cod", "ve may bay", "dat phong"], "new_beneficiary": true}'::jsonb, '{"SALARY": ["Bạn đã kiểm tra thông tin người bán ngoài nền tảng chat chưa?"], "HNW": ["Giao dịch này có qua sàn thương mại điện tử chính thức không?"], "SENIOR": ["Bác mua hàng này ở đâu, có phải qua tin nhắn Facebook không ạ?"]}'::jsonb, '["Người bán có cửa hàng rõ ràng", "Tôi chỉ liên hệ qua mạng xã hội", "Giá rẻ bất thường"]'::jsonb, 'Trả tiền khi nhận hàng, đừng cọc trước', 'Dấu hiệu của người bán giả: giá thấp bất thường so với thị trường, chỉ nhận chuyển khoản trước và từ chối giao dịch qua sàn có bảo vệ người mua, tài khoản nhận tiền mang tên khác với tên cửa hàng. Hãy ưu tiên thanh toán khi nhận hàng, hoặc giao dịch qua sàn thương mại điện tử chính thức nơi bạn có quyền khiếu nại.', 'contact', 4, 'ACTIVE'),
  ('S07', 'Thông báo trúng thưởng, yêu cầu đóng phí nhận quà', 'G4', 'SINGLE', 'Y', '{"keywords": ["trung thuong", "qua tang", "phi nhan thuong", "may man", "trung xe", "le phi"], "new_beneficiary": true}'::jsonb, '{"SALARY": ["Bạn có tham gia chương trình bốc thăm nào trước đó không?"], "HNW": ["Bên trao thưởng có yêu cầu bạn nộp phí trước khi nhận không?"], "SENIOR": ["Bác có nhớ mình đăng ký chương trình trúng thưởng này lúc nào không ạ?"]}'::jsonb, '["Tôi có tham gia", "Tôi không hề tham gia", "Họ bảo phải đóng thuế trước"]'::jsonb, 'Giải thưởng thật không thu phí trước', 'Theo quy định pháp luật, thuế thu nhập từ trúng thưởng được khấu trừ trực tiếp vào giá trị giải thưởng, người trúng không phải nộp tiền trước để nhận quà. Bất kỳ yêu cầu nộp ''phí vận chuyển'', ''thuế trước bạ'' hay ''phí làm hồ sơ'' nào cũng là lừa đảo. Đặc biệt cảnh giác nếu bạn chưa từng đăng ký tham gia chương trình đó.', 'cancel', 4, 'ACTIVE'),
  ('S08', 'Lừa đảo tình cảm, gửi quà từ nước ngoài', 'G4', 'SERIES', 'Y', '{"keywords": ["hai quan", "gui qua", "nuoc ngoai", "phi van chuyen", "kien hang", "bao hiem kien hang"], "new_beneficiary": true, "min_series_14d": 2}'::jsonb, '{"SALARY": ["Bạn đã gặp mặt trực tiếp người này chưa?"], "HNW": ["Khoản phí này có liên quan tới một kiện hàng gửi từ nước ngoài không?"], "SENIOR": ["Bác đã gặp người gửi quà này ngoài đời lần nào chưa ạ?"]}'::jsonb, '["Chưa gặp mặt bao giờ", "Đã gặp rồi", "Họ nói kiện hàng đang bị giữ"]'::jsonb, 'Hải quan không thu phí qua tài khoản cá nhân', 'Kịch bản quen thuộc: một người quen qua mạng nói đã gửi cho bạn kiện hàng giá trị lớn, sau đó một ''nhân viên hải quan'' liên hệ đòi phí thông quan, rồi phí bảo hiểm, rồi phí chống rửa tiền — mỗi lần một khoản, không bao giờ dứt. Cơ quan hải quan thật thu phí qua kho bạc nhà nước, không bao giờ qua tài khoản cá nhân. Nếu bạn chưa từng gặp mặt người đó ngoài đời, khả năng rất cao đây là lừa đảo.', 'hold', 4, 'ACTIVE'),
  ('S09', 'Chiếm quyền điều khiển thiết bị của khách', 'G5', 'TAKEOVER', 'N', '{"keywords": ["ho tro tu xa", "cai dat ung dung", "dich vu cong", "quyet toan thue", "ultraviewer", "teamviewer"], "session_flags": ["screen_sharing", "remote_app", "accessibility_service", "new_device"], "recent_events": ["NEW_DEVICE_LOGIN", "PASSWORD_RESET"], "min_drain_ratio": 0.6}'::jsonb, '{"SALARY": ["Giao dịch đã được tạm khóa để xác minh lại danh tính."], "HNW": ["Giao dịch đã được tạm khóa để xác minh lại danh tính."], "SENIOR": ["Giao dịch đã được tạm khóa để xác minh lại danh tính."]}'::jsonb, '["Xác thực sinh trắc học lại"]'::jsonb, 'Thiết bị của bạn có dấu hiệu bị điều khiển từ xa', 'Hệ thống phát hiện ứng dụng điều khiển từ xa hoặc dịch vụ trợ năng lạ đang hoạt động trên thiết bị của bạn. Trong tình huống này, người đang thao tác có thể không phải là bạn, nên chúng tôi tạm khóa giao dịch mà không hỏi thêm — nếu kẻ gian đang điều khiển máy, chính họ sẽ là người trả lời câu hỏi. Hãy gỡ các ứng dụng điều khiển từ xa vừa cài, khởi động lại thiết bị và xác thực sinh trắc học để mở khóa.', 'hold', 0, 'ACTIVE'),
  ('S10', 'Nhận tiền chuyển nhầm rồi bị đòi ''chuyển trả''', 'G1', 'RECEIVER', 'Y', '{"keywords": ["chuyen nham", "chuyen tra", "hoan lai", "nham tai khoan", "thu ho"], "recent_events": ["INBOUND_UNKNOWN"], "new_beneficiary": true, "inbound_bait": true}'::jsonb, '{"SALARY": ["Bạn có vừa nhận một khoản tiền lạ rồi được yêu cầu chuyển trả không?"], "HNW": ["Khoản chuyển trả này có đúng tài khoản đã chuyển tiền cho bạn không?"], "SENIOR": ["Bác có vừa nhận tiền của người lạ rồi họ gọi đòi lại không ạ?"]}'::jsonb, '["Đúng, họ bảo chuyển nhầm", "Không liên quan", "Họ giục tôi chuyển gấp"]'::jsonb, 'Đừng tự chuyển trả tiền chuyển nhầm', 'Nếu có người chuyển nhầm tiền vào tài khoản của bạn, cách xử lý đúng là báo ngân hàng để ngân hàng đối soát và hoàn trả theo quy trình — tuyệt đối không tự chuyển trả theo hướng dẫn qua điện thoại. Kẻ gian thường dùng tiền từ tài khoản ăn cắp để ''chuyển nhầm'', rồi yêu cầu bạn chuyển trả vào một tài khoản khác; khi chủ tài khoản thật khiếu nại, bạn vừa mất tiền vừa liên quan tới dòng tiền bất hợp pháp.', 'cancel', 3, 'ACTIVE');
INSERT INTO fraud_case (fraud_case_id, customer_id, scenario_id, pattern, description, injection, expected_level, expected_score_min, expected_score_max, demo_scene) VALUES
  ('F01', 100008, 'S01', 'DRAIN', 'Giả danh công an: tất toán sổ tiết kiệm rồi chuyển toàn bộ vào ''tài khoản an toàn''', '{"pre_events": ["SAVINGS_CLOSED"], "series": [{"amount": 560000000, "time": "15:20", "memo": "CHUYEN TIEN THEO YEU CAU CO QUAN DIEU TRA"}], "inbound_bait": null, "session_flags": {"on_call": true}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'intervene', 78, 100, 'Scene 3'),
  ('F02', 100008, 'S01', 'DRAIN', 'ĐỐI CHỨNG hợp lệ: cùng khách hàng chuyển khoản lớn cho con gái đã quen, không có sự kiện bất thường đi kèm — engine phải cho đi qua', '{"pre_events": [], "series": [{"amount": 60000000, "time": "10:25", "memo": "GUI CON GAI MUA XE"}], "inbound_bait": null, "session_flags": {}, "beneficiary_is_new": false, "drain_ratio": null}'::jsonb, 'pass', 0, 39, 'Scene 4'),
  ('F03', 100002, 'S02', 'SINGLE', 'Giả danh nhân viên ngân hàng moi OTP, đổi mật khẩu rồi rút tiền lúc nửa đêm', '{"pre_events": ["PASSWORD_RESET"], "series": [{"amount": 28000000, "time": "23:41", "memo": "NANG CAP BAO MAT TAI KHOAN"}], "inbound_bait": null, "session_flags": {"on_call": true}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'intervene', 75, 100, 'Scene 5'),
  ('F04', 100005, 'S03', 'SINGLE', 'Deepfake video call giả con trai bị tai nạn, xin chuyển gấp', '{"pre_events": ["NEW_DEVICE_LOGIN"], "series": [{"amount": 180000000, "time": "20:15", "memo": "CHUYEN GAP CHO CON"}], "inbound_bait": null, "session_flags": {"on_call": true, "new_device": true}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'intervene', 70, 95, NULL),
  ('F05', 100001, 'S04', 'SERIES', 'Sàn đầu tư ảo: nhận tiền mồi 8tr rồi nạp 3 lần tăng dần', '{"pre_events": [], "series": [{"amount": 6000000, "time": "20:30", "memo": "NAP DAU TU SAN QUOC TE"}, {"amount": 15000000, "time": "21:12", "memo": "NAP DAU TU SAN QUOC TE"}, {"amount": 32000000, "time": "23:47", "memo": "NAP THEM DE RUT LOI NHUAN"}], "inbound_bait": 8000000, "session_flags": {"on_call": true}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'intervene', 68, 95, NULL),
  ('F06', 100004, 'S05', 'SERIES', 'Việc nhẹ lương cao: làm nhiệm vụ nạp tiền 4 lần, hoa hồng mồi 2.5tr', '{"pre_events": [], "series": [{"amount": 2000000, "time": "21:10", "memo": "NAP NHIEM VU 1"}, {"amount": 6000000, "time": "20:35", "memo": "NAP NHIEM VU 2"}, {"amount": 14000000, "time": "22:18", "memo": "NAP NHIEM VU 3"}, {"amount": 30000000, "time": "23:52", "memo": "NAP NHIEM VU CUOI DE RUT"}], "inbound_bait": 2500000, "session_flags": {}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'intervene', 65, 95, NULL),
  ('F07', 100003, 'S06', 'SINGLE', 'Đặt cọc mua hàng online giá rẻ bất thường qua mạng xã hội', '{"pre_events": [], "series": [{"amount": 9000000, "time": "20:40", "memo": "DAT COC GIU CHO"}], "inbound_bait": null, "session_flags": {}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'soft_warn', 38, 72, NULL),
  ('F08', 100010, 'S08', 'SERIES', 'Lừa đảo tình cảm: đóng phí hải quan nhận kiện hàng từ nước ngoài, 2 lần', '{"pre_events": [], "series": [{"amount": 12000000, "time": "15:30", "memo": "PHI HAI QUAN KIEN HANG"}, {"amount": 22000000, "time": "16:20", "memo": "PHI BAO HIEM KIEN HANG"}], "inbound_bait": null, "session_flags": {}, "beneficiary_is_new": true, "drain_ratio": null}'::jsonb, 'intervene', 65, 95, NULL),
  ('F09', 100006, 'S09', 'TAKEOVER', 'Chiếm quyền điều khiển thiết bị qua ứng dụng ''dịch vụ công'' giả, vét tài khoản', '{"pre_events": ["NEW_DEVICE_LOGIN"], "series": [{"amount": 0, "time": "14:25", "memo": "QUYET TOAN THUE DICH VU CONG"}], "inbound_bait": null, "session_flags": {"screen_sharing": true, "remote_app": true, "accessibility_service": true, "new_device": true}, "beneficiary_is_new": true, "drain_ratio": 0.93}'::jsonb, 'intervene', 85, 100, 'Scene 6'),
