  ('29e847b4-c299-58d0-a34d-585030306acc', 100008, 5011, '{"amount": 60000000.0, "beneficiary_masked": "3028 ****", "bank_code": "VCB", "tx_time": "2026-09-02 10:25:00+07", "memo_masked": "GUI CON GAI MUA XE", "channel": "MOBILE", "session_flags": {}, "working_balance": 123075000.0}'::jsonb, 19, 'pass', '{"amount_deviation": {"score": 20}, "new_beneficiary": {"score": 0}, "time_of_day": {"score": 0}, "behavior_drift": {"score": 0}, "relationship_history": {"score": 0}, "recent_context": {"score": 0}}'::jsonb, 'none', NULL, 'Giao dịch 60,000,000 VND có điểm rủi ro 19/100.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-02 10:25:00+07', NULL, NULL),
  ('7d1a9ad4-c7f6-5edd-bd67-25d6ebf0dff2', 100002, 5002, '{"amount": 28000000.0, "beneficiary_masked": "1176 ****", "bank_code": "TPB", "tx_time": "2026-09-06 23:41:00+07", "memo_masked": "NANG CAP BAO MAT TAI KHOAN", "channel": "MOBILE", "session_flags": {"on_call": true}, "working_balance": 122870000.0}'::jsonb, 87, 'intervene', '{"amount_deviation": {"score": 25}, "new_beneficiary": {"score": 20}, "time_of_day": {"score": 10}, "behavior_drift": {"score": 12}, "relationship_history": {"score": 11}, "recent_context": {"score": 20}}'::jsonb, 'recent_context,new_beneficiary,amount_deviation', 'S02', 'Giao dịch 28,000,000 VND có điểm rủi ro 87/100.', '["Người nhận chưa từng xuất hiện trong lịch sử chuyển tiền của khách.", "Số tiền vượt xa mức khách thường chuyển trong 90 ngày qua.", "Có sự kiện bất thường xảy ra ngay trước lệnh chuyển."]'::jsonb, 'Có ai vừa yêu cầu bạn đọc mã OTP hoặc mật khẩu qua điện thoại không?', '["Có, tôi vừa đọc mã cho họ", "Không", "Tôi có bấm vào một đường link lạ"]'::jsonb, 'Khách đã chọn dừng giao dịch', 'Ngân hàng không bao giờ hỏi OTP', 'Không một nhân viên ngân hàng thật nào hỏi mã OTP, mật khẩu hay mã PIN của bạn — họ không cần và cũng không được phép. Mã OTP là chữ ký điện tử của riêng bạn: đọc cho người khác nghe đồng nghĩa với việc ký vào lệnh chuyển tiền của họ. Nếu bạn vừa cung cấp mã, hãy đổi mật khẩu ngay và gọi hotline ngân hàng.', 'cancel', 'cancel', 'prevented', '2026-09-06 23:41:00+07', '2026-09-06 23:41:18+07', '2026-09-06 23:42:01+07'),
  ('64540ef6-967a-59a8-8d7c-dae7631f0faf', 100005, 5005, '{"amount": 180000000.0, "beneficiary_masked": "7493 ****", "bank_code": "MBB", "tx_time": "2026-09-04 20:15:00+07", "memo_masked": "CHUYEN GAP CHO CON", "channel": "MOBILE", "session_flags": {"on_call": true, "new_device": true}, "working_balance": 3545854000.0}'::jsonb, 82, 'intervene', '{"amount_deviation": {"score": 25}, "new_beneficiary": {"score": 20}, "time_of_day": {"score": 0}, "behavior_drift": {"score": 12}, "relationship_history": {"score": 11}, "recent_context": {"score": 20}}'::jsonb, 'recent_context,new_beneficiary,amount_deviation', 'S03', 'Giao dịch 180,000,000 VND có điểm rủi ro 82/100.', '["Người nhận chưa từng xuất hiện trong lịch sử chuyển tiền của khách.", "Số tiền vượt xa mức khách thường chuyển trong 90 ngày qua.", "Có sự kiện bất thường xảy ra ngay trước lệnh chuyển."]'::jsonb, 'Yêu cầu chuyển gấp này đến từ video call hay tin nhắn?', '["Tôi gọi lại rồi, đúng là người nhà", "Chưa gọi lại", "Họ gọi video cho tôi"]'::jsonb, 'Khách đã chọn dừng giao dịch', 'Hãy gọi lại bằng số bạn vẫn lưu', 'Công nghệ deepfake hiện có thể dựng khuôn mặt và giọng nói người thân của bạn trong một cuộc gọi video ngắn. Dấu hiệu nhận biết: hình ảnh mờ hoặc giật, người gọi viện lý do mạng kém để cúp nhanh, và luôn hối thúc chuyển tiền gấp vào một tài khoản lạ. Cách kiểm tra chắc chắn nhất: cúp máy và tự gọi lại bằng số điện thoại bạn vẫn lưu trong danh bạ, hoặc hỏi một câu chỉ hai người mới biết.', 'hold', 'hold', 'held', '2026-09-04 20:15:00+07', '2026-09-04 20:15:25+07', '2026-09-04 20:18:08+07'),
  ('c0c989d3-67b3-55cc-ab9c-aaaafeccdf33', 100001, 5001, '{"amount": 32000000.0, "beneficiary_masked": "8633 ****", "bank_code": "TCB", "tx_time": "2026-09-08 23:47:00+07", "memo_masked": "NAP THEM DE RUT LOI NHUAN", "channel": "MOBILE", "session_flags": {"on_call": true}, "working_balance": 64231000.0}'::jsonb, 81, 'intervene', '{"amount_deviation": {"score": 25}, "new_beneficiary": {"score": 20}, "time_of_day": {"score": 10}, "behavior_drift": {"score": 12}, "relationship_history": {"score": 11}, "recent_context": {"score": 0}}'::jsonb, 'recent_context,new_beneficiary,amount_deviation', 'S04', 'Giao dịch 32,000,000 VND có điểm rủi ro 81/100.', '["Người nhận chưa từng xuất hiện trong lịch sử chuyển tiền của khách.", "Số tiền vượt xa mức khách thường chuyển trong 90 ngày qua.", "Có sự kiện bất thường xảy ra ngay trước lệnh chuyển."]'::jsonb, 'Sàn đầu tư này có được Ủy ban Chứng khoán Nhà nước cấp phép không?', '["Tôi đã rút được tiền vài lần", "Chưa rút được lần nào", "Có người quen giới thiệu"]'::jsonb, 'Khách đã chọn dừng giao dịch', 'Rút được lần đầu là cách họ lấy niềm tin', 'Mô hình sàn đầu tư ảo luôn cho bạn rút được vài lần đầu với số nhỏ — đó chính là khoản ''tiền mồi'' để bạn tin tưởng và nạp số lớn hơn. Đến khi bạn nạp khoản lớn, sàn sẽ báo lỗi hệ thống, yêu cầu nộp thêm ''thuế'' hoặc ''phí rút'', rồi biến mất. Không có kênh đầu tư hợp pháp nào cam kết lợi nhuận cố định trên 15%/năm. Hãy tra cứu giấy phép trên trang của Ủy ban Chứng khoán Nhà nước trước khi nạp thêm bất kỳ đồng nào.', 'hold', 'hold', 'held', '2026-09-08 23:47:00+07', '2026-09-08 23:47:10+07', '2026-09-08 23:50:55+07'),
  ('ec33661a-6f4e-5765-b1ef-56330e8c87b1', 100004, 5004, '{"amount": 30000000.0, "beneficiary_masked": "8860 ****", "bank_code": "VPB", "tx_time": "2026-09-09 23:52:00+07", "memo_masked": "NAP NHIEM VU CUOI DE RUT", "channel": "MOBILE", "session_flags": {}, "working_balance": 73737000.0}'::jsonb, 80, 'intervene', '{"amount_deviation": {"score": 25}, "new_beneficiary": {"score": 20}, "time_of_day": {"score": 10}, "behavior_drift": {"score": 0}, "relationship_history": {"score": 11}, "recent_context": {"score": 0}}'::jsonb, 'recent_context,new_beneficiary,amount_deviation', 'S05', 'Giao dịch 30,000,000 VND có điểm rủi ro 80/100.', '["Người nhận chưa từng xuất hiện trong lịch sử chuyển tiền của khách.", "Số tiền vượt xa mức khách thường chuyển trong 90 ngày qua.", "Có sự kiện bất thường xảy ra ngay trước lệnh chuyển."]'::jsonb, 'Bạn có phải nạp tiền trước để nhận hoa hồng cho nhiệm vụ này không?', '["Có, tôi phải nạp trước", "Không", "Nhiệm vụ này là nhiệm vụ cuối"]'::jsonb, 'Khách đã chọn dừng giao dịch', 'Việc làm thật không bắt bạn nạp tiền', 'Không có công việc hợp pháp nào yêu cầu người lao động nạp tiền trước để nhận hoa hồng. Mô hình này luôn diễn ra theo cùng một kịch bản: vài nhiệm vụ đầu trả hoa hồng đầy đủ, rồi số tiền yêu cầu nạp tăng dần, và ở nhiệm vụ cuối họ báo bạn ''thao tác sai'' nên phải nạp thêm để lấy lại toàn bộ. Số tiền bạn đã nạp càng lớn thì áp lực nạp tiếp càng mạnh — đó là lúc nên dừng lại hoàn toàn.', 'hold', 'hold', 'held', '2026-09-09 23:52:00+07', '2026-09-09 23:52:14+07', '2026-09-09 23:54:47+07'),
  ('5f7b59ae-40d0-5fe2-be09-292e6ca5f57d', 100003, 5003, '{"amount": 9000000.0, "beneficiary_masked": "4138 ****", "bank_code": "ACB", "tx_time": "2026-09-05 20:40:00+07", "memo_masked": "DAT COC GIU CHO", "channel": "MOBILE", "session_flags": {}, "working_balance": 111536000.0}'::jsonb, 55, 'soft_warn', '{"amount_deviation": {"score": 9}, "new_beneficiary": {"score": 20}, "time_of_day": {"score": 0}, "behavior_drift": {"score": 0}, "relationship_history": {"score": 11}, "recent_context": {"score": 0}}'::jsonb, 'new_beneficiary,amount_deviation,relationship_history', 'S06', 'Giao dịch 9,000,000 VND có điểm rủi ro 55/100.', '["Người nhận chưa từng xuất hiện trong lịch sử chuyển tiền của khách.", "Số tiền vượt xa mức khách thường chuyển trong 90 ngày qua.", "Có sự kiện bất thường xảy ra ngay trước lệnh chuyển."]'::jsonb, 'Bạn đã kiểm tra thông tin người bán ngoài nền tảng chat chưa?', '["Người bán có cửa hàng rõ ràng", "Tôi chỉ liên hệ qua mạng xã hội", "Giá rẻ bất thường"]'::jsonb, NULL, 'Trả tiền khi nhận hàng, đừng cọc trước', 'Dấu hiệu của người bán giả: giá thấp bất thường so với thị trường, chỉ nhận chuyển khoản trước và từ chối giao dịch qua sàn có bảo vệ người mua, tài khoản nhận tiền mang tên khác với tên cửa hàng. Hãy ưu tiên thanh toán khi nhận hàng, hoặc giao dịch qua sàn thương mại điện tử chính thức nơi bạn có quyền khiếu nại.', 'contact', 'continue', 'proceeded', '2026-09-05 20:40:00+07', '2026-09-05 20:40:13+07', '2026-09-05 20:43:35+07'),
